<template><label class="ln-date-field"><span v-if="label">{{label}}</span><div><LnIcon name="calendar"/><input :value="modelValue" type="date" :disabled="disabled" @input="update"/><button v-if="clearable&&modelValue" type="button" aria-label="清除日期" @click="clear"><LnIcon name="close"/></button></div></label></template>
<script setup lang="ts">import LnIcon from './LnIcon.vue';withDefaults(defineProps<{modelValue?:string;label?:string;clearable?:boolean;disabled?:boolean}>(),{modelValue:''});const emit=defineEmits<{(e:'update:modelValue',value:string):void;(e:'change',value:string):void}>();function setValue(value:string){emit('update:modelValue',value);emit('change',value)}function update(e:Event){setValue((e.target as HTMLInputElement).value)}function clear(){setValue('')}</script>
<style scoped lang="scss">.ln-date-field{display:grid;gap:6px;font-family:var(--ln-font);>span{font-size:13px;font-weight:540}>div{height:var(--ln-control-md);padding:0 8px;display:flex;align-items:center;gap:7px;border:1px solid var(--ln-border-strong);border-radius:var(--ln-radius-md);background:var(--ln-surface);>svg{width:15px;height:15px;color:var(--ln-icon)}&:focus-within{border-color:rgba(94,106,210,.62);box-shadow:0 0 0 2px var(--ln-accent-soft)}input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:var(--ln-text);font:13px var(--ln-font)}button{width:24px;height:24px;display:grid;place-items:center;border:0;background:none;color:var(--ln-icon-muted);cursor:pointer;svg{width:14px;height:14px}}}}</style>
